import type { EmailIntakeMessage } from './email-intake-message-model';
import type { Request } from './request-model';

export const EmailRequestLinkRelationshipTypeKeyToLabel = {
  'Origin': 'Origin',
  'Reply': 'Reply'
} as const;
export type EmailRequestLinkRelationshipTypeKey = keyof typeof EmailRequestLinkRelationshipTypeKeyToLabel;

export interface EmailRequestLink {
  /**
   * @displayName Email Request Link ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Link Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  linkName: string;
  /**
   * @displayName Conversation ID
   * @validationRule Required for create/update operations
   */
  conversationID: string;
  /**
   * @displayName Email Intake Message
   * @validationRule Required for create/update operations
   */
  emailIntakeMessage: Pick<EmailIntakeMessage, 'id' | 'messageName'>;
  /**
   * @displayName Internet Message ID
   * @validationRule Required for create/update operations
   */
  internetMessageID: string;
  /**
   * @displayName Linked At
   * @validationRule Required for create/update operations
   */
  linkedAt: string;
  /**
   * @displayName Relationship Type
   * @validationRule Required for create/update operations
   */
  relationshipTypeKey: EmailRequestLinkRelationshipTypeKey;
  /**
   * @displayName Request
   * @validationRule Required for create/update operations
   */
  request: Pick<Request, 'id' | 'requestNumber'>;
}

export const _EmailRequestLink = 'EmailRequestLink' as const;